{
  "findings": [
    {
      "check_id": "CKV_GCP_93",
      "title": "Compute disk lacks customer-managed encryption",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The disk relies on Google-managed encryption because no customer-managed encryption key is configured. This limits control over key rotation, revocation, access auditing, and compliance enforcement."
    }
  ],
  "patched_code": "variable "changeme_google_attached_disk_kms_key_self_link" {
  description = "Self-link of the Cloud KMS CryptoKey used to encrypt the attached disks. The key must be available in us-central1."
  type        = string
}

resource "google_compute_disk" "changeme_count_attached_disk_disk" {
  name                      = "changeme-count-attached-disk-disk-${count.index}"
  count                     = var.changeme_google_attached_disk_count_number_of_instances
  type                      = "pd-ssd"
  zone                      = "us-central1-a"
  size                      = 4
  physical_block_size_bytes = 4096

  disk_encryption_key {
    kms_key_self_link = var.changeme_google_attached_disk_kms_key_self_link
  }
}
",
  "fix_summary": "Configured the disks to use a caller-supplied Cloud KMS key and added a typed variable for its self-link. No key material or placeholder credentials were embedded in the configuration."
}
